import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, lineTotal, lineDiscount, lineVAT } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns DATE_INVALID for invalid asOf date', () => {
  const r = overdueInvoices([], 'not-a-date');
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices with no invoices returns empty list', () => {
  const r = overdueInvoices([], '2026-10-07');
  assert.equal(r.ok, true);
  assert.deepEqual(r.value, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const r = overdueInvoices([draft.value], '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-05' });
  const r = overdueInvoices([paid.value], '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices includes issued invoices with dueDate before asOf', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const r = overdueInvoices([issued.value], '2026-10-20');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].number, issued.value.number);
});

test('overdueInvoices excludes issued invoices with dueDate on or after asOf', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const r = overdueInvoices([issued.value], '2026-10-15');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices includes partially_paid invoices with dueDate before asOf', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const partial = recordPayment(issued.value, { amount: 10000, date: '2026-10-10' });
  const r = overdueInvoices([partial.value], '2026-10-20');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].number, issued.value.number);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const r = overdueInvoices([issued.value], '2026-10-25');
  assert.equal(r.ok, true);
  assert.equal(r.value[0].daysOverdue, 10);
});

test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const draft2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(draft1.value, []);
  const issued2 = issueInvoice(draft2.value, ['INV-2026-0001']);
  const r = overdueInvoices([issued1.value, issued2.value], '2026-10-25');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 2);
  assert.equal(r.value[0].daysOverdue, 10);
  assert.equal(r.value[1].daysOverdue, 6);
});

test('overdueInvoices includes required fields: number, customerId, dueDate, daysOverdue, due', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const r = overdueInvoices([issued.value], '2026-10-25');
  assert.equal(r.ok, true);
  const inv = r.value[0];
  assert.equal(typeof inv.number, 'string');
  assert.match(inv.number, /^INV-/);
  assert.equal(typeof inv.customerId, 'string');
  assert.match(inv.customerId, /^C-/);
  assert.equal(inv.dueDate, '2026-10-15');
  assert.equal(typeof inv.daysOverdue, 'number');
  assert.equal(inv.daysOverdue > 0, true);
  assert.equal(typeof inv.due, 'number');
  assert.equal(inv.due > 0, true);
});

test('overdueInvoices calculates due correctly for unpaid invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const r = overdueInvoices([issued.value], '2026-10-25');
  assert.equal(r.ok, true);
  assert.equal(r.value[0].due, totals.total);
});

test('overdueInvoices calculates due correctly for partially paid invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const partial = recordPayment(issued.value, { amount: 5000, date: '2026-10-10' });
  const r = overdueInvoices([partial.value], '2026-10-25');
  assert.equal(r.ok, true);
  assert.equal(r.value[0].due, totals.total - 5000);
});

test('overdueInvoices with multiple customers and statuses', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(draft1.value, []);
  const issued2 = issueInvoice(draft2.value, ['INV-2026-0001']);
  const partial = recordPayment(issued2.value, { amount: 10000, date: '2026-10-10' });
  const r = overdueInvoices([issued1.value, partial.value], '2026-10-25');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 2);
  assert.equal(r.value[0].customerId, 'C-001');
  assert.equal(r.value[1].customerId, 'C-002');
});

test('overdueInvoices with invoices exactly on dueDate', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
  const r = overdueInvoices([issued.value], '2026-10-15');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices day after dueDate is overdue', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(draft.value, []);
